-- CARTA_JOGO — PARTE 4 de 4 · cole no SQL Editor do Supabase e clique RUN
set default_transaction_read_only = off;
on conflict(card_id) do update set temporada=excluded.temporada,tipo=excluded.tipo,overall=excluded.overall,roda_motor=excluded.roda_motor,nome=case when excluded.nome<>'' then excluded.nome else clube.carta_jogo.nome end,posicao=excluded.posicao,estilo_of=excluded.estilo_of,estilo_of_id=excluded.estilo_of_id,estilo_of_novo=excluded.estilo_of_novo,estilo_def=excluded.estilo_def,estilo_def_id=excluded.estilo_def_id,estilo_def_novo=excluded.estilo_def_novo,impeto_s1=excluded.impeto_s1,impeto_s2_cond=excluded.impeto_s2_cond,atributos=excluded.atributos;
